class Initializer:
    # Credentials and app URL are read lazily via properties so that
    # load_dotenv() above has already populated os.environ by the time
    # these values are first accessed — even when PyCharm imports this
    # module before the runner's own load_dotenv() call.
    @staticmethod
    def _username():
        return os.environ.get("BROWSERSTACK_USERNAME", "your_username_here")

    @staticmethod
    def _access_key():
        return os.environ.get("BROWSERSTACK_ACCESS_KEY", "your_access_key_here")

    @staticmethod
    def _app_url():
        return os.environ.get("AppURL", "bs://2cb25d26a5b87168117ec49799f3cc5e51756e61")

    @staticmethod
    def _hub_url():
        u = os.environ.get("BROWSERSTACK_USERNAME", "your_username_here")
        k = os.environ.get("BROWSERSTACK_ACCESS_KEY", "your_access_key_here")
        return f"https://{u}:{k}@hub-cloud.browserstack.com/wd/hub"

    # Keep class-level aliases for backward compatibility with customer code
    # that reads Initializer.USERNAME / Initializer.ACCESS_KEY directly.
    # These are re-evaluated each time they are accessed via the property trick.
    USERNAME   = property(lambda self: os.environ.get("BROWSERSTACK_USERNAME", "your_username_here"))
    ACCESS_KEY = property(lambda self: os.environ.get("BROWSERSTACK_ACCESS_KEY", "your_access_key_here"))
    APP_URL    = property(lambda self: os.environ.get("AppURL", "bs://2cb25d26a5b87168117ec49799f3cc5e51756e61"))
    HUB_URL    = property(lambda self: Initializer._hub_url())
